from interops.libraries.squish_actions import CommonActions
from interops.libraries.mosaiq.interactions.objects.mosaiq_staff_tps_security_objects import TpsSecurityObjects

class TpsSecurity:
    """
    Class for TPS Security window operataions.

    Use property getter and setter for each data item.

    """
    def __init__(self) -> None:
        pass
        #CommonActions.wait_for_object_exists(TpsSecurityObjects.tPS_Security_Window)

    @property
    def globalsetting_modify(self):
        self._globalsetting_modify = get_checked(TpsSecurityObjects.global_Settings_WindowsFormsControl)
        return self._globalsetting_modify

    @globalsetting_modify.setter
    def globalsetting_modify(self, value):
        set_checked(TpsSecurityObjects.global_Settings_WindowsFormsControl, value)

    @property
    def physicsdata_modify(self):
        self._globalsetting_modify = get_checked(TpsSecurityObjects.physics_Data_WindowsFormsControl)
        return self._globalsetting_modify

    @physicsdata_modify.setter
    def get_physicsdata_modify(self, value):
        set_checked(TpsSecurityObjects.physics_Data_WindowsFormsControl, value)

    @property
    def plandata_modify(self):
        self._plandata_modify = get_checked(TpsSecurityObjects.plan_Data_WindowsFormsControl)
        return self._plandata_modify

    @plandata_modify.setter
    def plandata_modify(self, value):
        set_checked(TpsSecurityObjects.plan_Data_WindowsFormsControl, value)

    @property
    def planapproval_approve(self):
        self._planapproval_approve = get_checked(TpsSecurityObjects.plan_Approve_WindowsFormsControl)
        return self._planapproval_approve

    @planapproval_approve.setter
    def get_planapproval_approve(self, value):
        set_checked(TpsSecurityObjects.plan_Approve_WindowsFormsControl, value)

    @property
    def exportdata_modify(self):
        self._exportdata_modify = get_checked(TpsSecurityObjects.export_Data_WindowsFormsControl)
        return self._exportdata_modify

    @exportdata_modify.setter
    def exportdata_modify(self, value):
        set_checked(TpsSecurityObjects.export_Data_WindowsFormsControl, value)

    @staticmethod
    def click_OK_button():
        CommonActions.left_click_object(TpsSecurityObjects.oK_WindowsFormsControl)

    @staticmethod
    def click_Cancel_button():
        CommonActions.left_click_object(TpsSecurityObjects.cancel_WindowsFormsControl)

def get_checked(o_map: dict):
    '''Get the checked state of a windows .net control that has Checked attribute'''
    obj = CommonActions.find_object(o_map)
    if obj:
        return obj.nativeObject.Checked
    raise ValueError

def set_checked(o_map: dict, on: bool):
    '''Set the checked state of a windows .net control that has Checked attribute'''
    obj = CommonActions.find_object(o_map)
    if obj and obj.nativeObject.Checked != on:
        CommonActions.left_click_object_no_move(obj)
